// after: 'refactored with the patterns'
+const BadgeCountContext = createContext<number | null>(null);
+function Badge({ items, children }: { items: Item[]; children: React.ReactNode }) {
+  const visible = useMemo(() => items.filter((i) => i.active), [items]);
+  const count = useMemo(() => visible.length, [visible]);
+  return (
+    <ErrorBoundary fallback={<span>error</span>}>
+      <BadgeCountContext.Provider value={count}>{children}</BadgeCountContext.Provider>
+    </ErrorBoundary>
+  );
+}
+Badge.Count = function Count() {
+  const count = useContext(BadgeCountContext)!;
+  return <span>Active: {count}</span>;
+};
+// used in exactly one place, always as <Badge items={x}><Badge.Count/></Badge>
